// Pass-through: forwards sender_email and thread_id from parent workflow
// When testing manually, set values in Execute Workflow Trigger's jsonExample
const input = $input.first().json;
return [{ json: {
  sender_email: input.sender_email || null,
  thread_id: input.thread_id || null
}}];

const triggerData = $('Execute Workflow Trigger').first().json;
const senderEmail = triggerData.sender_email;
const searchResult = $input.first().json;
const API_TOKEN = '86eda7172621e731a5c482c52306d395ba35e193';

if (!searchResult.data?.items?.length) {
  return [{ json: {
    fetch_url: 'https://api.pipedrive.com/v1/persons/0/deals?status=open&api_token=' + API_TOKEN,
    person_id: null, name: null, org_name: null, org_id: null,
    email: senderEmail, new_contact: true, source: 'none', is_primary: true
  }}];
}

const persons = searchResult.data.items;
const items = [];
const seenOrgs = new Set();

for (let i = 0; i < persons.length; i++) {
  const p = persons[i].item;
  items.push({ json: {
    fetch_url: `https://api.pipedrive.com/v1/persons/${p.id}/deals?status=open&api_token=${API_TOKEN}`,
    person_id: p.id, name: p.name,
    org_name: p.organization?.name || null,
    org_id: p.organization?.id || null,
    email: p.primary_email || senderEmail,
    new_contact: false, source: 'person', is_primary: i === 0
  }});
  if (p.organization?.id && !seenOrgs.has(p.organization.id)) {
    seenOrgs.add(p.organization.id);
    items.push({ json: {
      fetch_url: `https://api.pipedrive.com/v1/organizations/${p.organization.id}/deals?status=open&api_token=${API_TOKEN}`,
      person_id: p.id, name: p.name,
      org_name: p.organization.name || null,
      org_id: p.organization.id,
      email: p.primary_email || senderEmail,
      new_contact: false, source: 'org', is_primary: false
    }});
  }
}

return items;

const serviceMap = {9:'Screenprint',10:'DTG',12:'Sublimation',14:'Embroidery',15:'Promo Products',17:'Knit Socks',18:'Sub Socks',21:'Custom Socks'};
const stageMap = {1:'Uncontacted',2:'In Contact',3:'Preparing Quotation',4:'Quote Sent',5:'Won',6:'Lost'};
const FIELD_SERVICE = 'ac41974cf4da3eabc2955b5533f80df058c53b2b';
const FIELD_QTY = 'eec1f00a2a01851427b5908878ced3888bd5c67a';
const FIELD_DEADLINE = '86ac6f8ccf0b48b75082fbea2c56136468184f0c';
const FIELD_ITEM = '85bda8a90660cd42d96b3cc497c83a2cacf80b38';

const allItems = $input.all();
const personMeta = $('Step 1b - Parse Persons').all();

let identity = null;
let deals = [];

// Find first item with deals, prefer person-source over org-source
const personItems = [];
const orgItems = [];
for (let i = 0; i < allItems.length; i++) {
  const meta = personMeta[i]?.json || {};
  const resp = allItems[i].json;
  const rawDeals = resp?.data || [];
  if (meta.source === 'person') personItems.push({ meta, rawDeals });
  else orgItems.push({ meta, rawDeals });
}

let winner = personItems.find(x => x.rawDeals.length > 0) || orgItems.find(x => x.rawDeals.length > 0);

if (winner) {
  const m = winner.meta;
  identity = { person_id: m.person_id, name: m.name, org_name: m.org_name, email: m.email, new_contact: false };
  const sorted = winner.rawDeals.sort((a, b) => new Date(b.update_time) - new Date(a.update_time)).slice(0, 3);
  deals = sorted.map((d, i) => ({
    deal_id: d.id, title: d.title,
    stage: stageMap[d.stage_id] || 'Stage ' + d.stage_id,
    value: d.value || 0, owner: d.owner_name || null,
    service_type: serviceMap[d[FIELD_SERVICE]] || d[FIELD_SERVICE] || null,
    quantity: d[FIELD_QTY] || null, deadline: d[FIELD_DEADLINE] || null,
    item_of_interest: d[FIELD_ITEM] || null, is_most_recent: i === 0
  }));
} else {
  const primary = personMeta.find(x => x.json.is_primary)?.json || personMeta[0]?.json || {};
  identity = {
    person_id: primary.person_id || null, name: primary.name || null,
    org_name: primary.org_name || null, email: primary.email || null,
    new_contact: primary.new_contact || false
  };
}

return [{ json: { identity, deals } }];

const prev = $input.first().json;
const deals = prev.deals || [];

if (deals.length === 0) {
  return [{ json: { ...prev, order: null, _skip_monday: true, request_body: '{}' } }];
}

const searchTerm = deals[0]?.title || '';
if (!searchTerm) {
  return [{ json: { ...prev, order: null, _skip_monday: true, request_body: '{}' } }];
}

const boardIds = [2042671018, 2071545220, 2071545115, 18391899286, 2469909693, 8097949101, 8133495678, 2072296463];
const escapedTerm = searchTerm.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

const query = `query { boards(ids: [${boardIds.join(',')}]) { id name items_page(limit: 3, query_params: { rules: [{ column_id: \"name\", compare_value: [\"${escapedTerm}\"] }] }) { items { id name column_values { id text } } } } }`;

return [{ json: { ...prev, _skip_monday: false, _search_term: searchTerm, request_body: JSON.stringify({ query }) } }];

