    const items = board.items_page?.items || [];
    if (items.length === 0) continue;
    const item = items[0];
    const meta = boardMeta[String(board.id)] || { name: board.name, statusCols: {} };
    const colMap = {};
    for (const cv of item.column_values) colMap[cv.id] = cv.text || '';
    const statuses = {};
    for (const [colId, label] of Object.entries(meta.statusCols)) {
      if (colMap[colId]) statuses[label] = colMap[colId];
    }
    let eta = null, vendor = null, vendorDue = null, svcType = null;
    if (meta.extraCols) {
      for (const [colId, field] of Object.entries(meta.extraCols)) {
        if (field === 'eta') eta = colMap[colId] || null;
        if (field === 'vendor') vendor = colMap[colId] || null;
        if (field === 'vendor_due_date') vendorDue = colMap[colId] || null;
        if (field === 'service_type') svcType = colMap[colId] || null;
      }
    }
    const statusParts = Object.entries(statuses).filter(([_,v]) => v).map(([k,v]) => k+': '+v);
    let human = 'In '+meta.name.toLowerCase();
    if (statusParts.length > 0) human += ' — '+statusParts.join(', ');
