    order = { found_on_board: meta.name, board_id: String(board.id), item_name: item.name, monday_item_id: item.id, statuses, eta, vendor, vendor_due_date: vendorDue, service_type: svcType, human_readable: human };
    break;
  }
} catch(e) {}

const { _skip_monday, _search_term, request_body, ...rest } = prev;
