const upstreamData = $('Step 3c - Parse Monday').first().json;
let financials = { outstanding_balance: 0, last_payment_date: null, open_invoices: [] };
try {
  const qbResult = $input.first().json;
  if (qbResult.error || !qbResult.QueryResponse) return [{ json: { ...upstreamData, financials } }];
  const invoices = qbResult.QueryResponse?.Invoice || [];
  let totalBalance = 0;
  const openInvs = [];
  for (const inv of invoices) {
    const balance = parseFloat(inv.Balance) || 0;
    if (balance > 0) { totalBalance += balance; openInvs.push({ doc_number: inv.DocNumber || null, amount: balance, due_date: inv.DueDate || null }); }
  }
  financials = { outstanding_balance: Math.round(totalBalance * 100) / 100, last_payment_date: null, open_invoices: openInvs };
} catch (err) {}
return [{ json: { ...upstreamData, financials } }];

