const prev = $('Step 4b - Parse Financials').first().json;
const gmailResult = $input.first().json;

let thread = { summary: null, message_count: 0, last_message_from: null };
let request_body = '';
let _skip_anthropic = true;

try {
  if (gmailResult.error || !gmailResult.messages) {
    return [{ json: { ...prev, thread, request_body, _skip_anthropic } }];
  }
  const messages = gmailResult.messages || [];
  thread.message_count = messages.length;
  if (messages.length > 0) {
    const lastMsg = messages[messages.length - 1];
    const fromHeader = (lastMsg.payload?.headers || []).find(h => h.name.toLowerCase() === 'from');
    thread.last_message_from = fromHeader?.value || null;
  }
  const findPart = (parts, mime) => {
    for (const part of parts) {
      if (part.mimeType === mime && part.body?.data) return Buffer.from(part.body.data, 'base64url').toString('utf-8');
      if (part.parts) { const found = findPart(part.parts, mime); if (found) return found; }
    }
    return null;
  };
  const stripHtml = (html) => html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/?(p|div|tr|li|h[1-6])[^>]*>/gi,'\n').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/\n{3,}/g,'\n\n').trim();
  const recentMsgs = messages.slice(-5);
  const cleanedParts = [];
  for (const msg of recentMsgs) {
    const from = (msg.payload?.headers || []).find(h => h.name.toLowerCase() === 'from')?.value || 'Unknown';
    const date = (msg.payload?.headers || []).find(h => h.name.toLowerCase() === 'date')?.value || '';
    const parts = msg.payload?.parts || [];
    let body = findPart(parts, 'text/plain');
    if (!body) { const html = findPart(parts, 'text/html'); if (html) body = stripHtml(html); }
    if (!body && msg.payload?.body?.data) {
      const raw = Buffer.from(msg.payload.body.data, 'base64url').toString('utf-8');
      body = raw.includes('<') ? stripHtml(raw) : raw;
    }
    if (!body) continue;
    body = body.split('\n').filter(line => !line.trim().startsWith('>')).join('\n');
    body = body.replace(/On .+wrote:\s*/gi, '');
    const sigPatterns = [/^--\s*$/m, /^_{3,}/m, /^Sent from my /m, /^Get Outlook for/m];
    for (const p of sigPatterns) { const m = body.search(p); if (m > 0) body = body.substring(0, m); }
    body = body.replace(/\n{3,}/g, '\n\n').trim();
    if (body.length > 0) cleanedParts.push('--- ' + from + ' (' + date + ') ---\n' + body);
  }
  const cleanedThread = cleanedParts.join('\n\n').substring(0, 3000);
  if (cleanedThread) {
    _skip_anthropic = false;
    const prompt = 'Summarize this email thread in 2-3 sentences for a customer service rep at a custom apparel printing company. Focus on: what the customer wants, any pending questions, and the current state of the conversation. Be specific.\n\nThread:\n' + cleanedThread;
    request_body = JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 200, messages: [{ role: 'user', content: prompt }] });
  }
} catch (err) {}

return [{ json: { ...prev, thread, request_body, _skip_anthropic } }];

