const prev = $('Step 2b - Merge Deals').first().json;
const notesResp = $input.first().json;

let deal_context = null;

try {
  const notes = notesResp?.data || [];

  if (notes.length > 0 && prev.deals && prev.deals.length > 0) {
    // First priority: find a pinned note (DEALCONTEXT output)
    const pinned = notes.find(n => n.pinned_to_deal_flag === 1 || n.pinned_to_deal_flag === true);

    if (pinned) {
      // Strip HTML tags from the note content
      let content = (pinned.content || '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/?(p|div|li|ul|ol|h[1-6])[^>]*>/gi, '\n')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&#39;/g, "'")
        .replace(/&quot;/g, '"')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

      // Cap at 3000 chars to stay within token limits
      if (content.length > 3000) content = content.substring(0, 3000) + '\n[...truncated]';

      deal_context = {
        source: 'pinned_note',
        deal_id: prev.deals[0].deal_id,
        deal_title: prev.deals[0].title || '',
        note_id: pinned.id,
        updated_at: pinned.update_time || pinned.add_time || null,
        content: content
      };
    } else {
      // Fallback: grab the most recent note (could be a call transcript or manual note)
      const latest = notes[0];
      let content = (latest.content || '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/?(p|div|li|ul|ol|h[1-6])[^>]*>/gi, '\n')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&#39;/g, "'")
        .replace(/&quot;/g, '"')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

      if (content.length > 2000) content = content.substring(0, 2000) + '\n[...truncated]';

      deal_context = {
        source: 'latest_note',
        deal_id: prev.deals[0].deal_id,
        deal_title: prev.deals[0].title || '',
        note_id: latest.id,
        updated_at: latest.update_time || latest.add_time || null,
        content: content
      };
    }
  }
} catch(e) {
  // Graceful degradation — enricher continues without deal context
}

return [{ json: { ...prev, deal_context } }];
